const fs = require('fs');
const readline = require('readline');
const path = require('path');

const transcriptPath = 'C:/Users/admin/.gemini/antigravity-ide/brain/53b57104-e4e2-40d0-adc5-813cc565893f/.system_generated/logs/transcript_full.jsonl';

async function dumpStep() {
  const fileStream = fs.createReadStream(transcriptPath);
  const rl = readline.createInterface({
    input: fileStream,
    crlfDelay: Infinity
  });

  for await (const line of rl) {
    if (!line.trim()) continue;
    const step = JSON.parse(line);
    if (step.step_index === 567) {
      console.log(`\n--- Step ${step.step_index} ---`);
      console.log(JSON.stringify(step, null, 2).substring(0, 2000));
    }
  }
}

dumpStep().catch(err => console.error(err));
